const { DatabaseSync } = require("node:sqlite");

const db = new DatabaseSync("data/clubs.db");

function listClubs(focus) {
  if (focus) {
    return db
      .prepare(`
        SELECT id, name, focus
        FROM clubs
        WHERE focus = ?
        ORDER BY id
      `)
      .all(focus);
  }

  return db
    .prepare(`
      SELECT id, name, focus
      FROM clubs
      ORDER BY id
    `)
    .all();
}

console.log(listClubs("engineering"));

sketchBlocks.bodyMarkdown:
Once repository functions exist, an Express route can focus on request parsing and response behavior.

```js
app.get("/api/events/:id", (req, res) => {
  const id = Number(req.params.id);
  const event = findEventById(id);

  if (!event) {
    return res.status(404).json({ error: "Event not found" });
  }

  return res.status(200).json(event);
});
```

**Step by step:** the route reads and normalizes the HTTP parameter, calls the repository with a plain id, checks whether a row was returned, preserves the existing `404` contract, and returns the same success JSON shape. The SQL is no longer mixed into route logic.

Changing the storage layer should not force the frontend-facing HTTP contract to change.

